      span.event(name, convertOtelTimeInput(startTime, clock), attributes)
      return self
    },
    addLink(link) {
      span.addLinks([{
        span: makeExternalSpan(link.context),
        attributes: link.attributes ?? {}
      }])
      return self
    },
    addLinks(links) {
      span.addLinks(links.map((link) => ({
        span: makeExternalSpan(link.context),
        attributes: link.attributes ?? {}
      })))
